// Async Dart example 06
Future<String> fetchUser06(int id) async {
  await Future<void>.delayed(Duration(milliseconds: 50));
  if (id < 0) throw ArgumentError('id cannot be negative');
  return 'user_$id';
}

Stream<int> countdown06(int start) async* {
  for (var value = start; value >= 0; value--) {
    await Future<void>.delayed(Duration(milliseconds: 10));
    yield value;
  }
}

Future<void> main() async {
  try {
    final user = await fetchUser06(6);
    print('Fetched: $user');

    await for (final value in countdown06(3)) {
      print('Tick: $value');
    }
  } catch (error) {
    print('Error: $error');
  }
}

