// Flutter-like ViewModel example 15, pure Dart
class Todo15 {
  final String id;
  final String title;
  final bool completed;

  const Todo15({required this.id, required this.title, this.completed = false});

  Todo15 copyWith({String? id, String? title, bool? completed}) {
    return Todo15(
      id: id ?? this.id,
      title: title ?? this.title,
      completed: completed ?? this.completed,
    );
  }
}

class TodoViewModel15 {
  final List<Todo15> _todos = [];

  List<Todo15> get todos => List.unmodifiable(_todos);

  void add(String title) {
    if (title.trim().isEmpty) throw ArgumentError('title cannot be empty');
    _todos.add(Todo15(id: DateTime.now().microsecondsSinceEpoch.toString(), title: title));
  }

  void toggle(String id) {
    final index = _todos.indexWhere((todo) => todo.id == id);
    if (index == -1) return;
    final todo = _todos[index];
    _todos[index] = todo.copyWith(completed: !todo.completed);
  }

  void removeCompleted() {
    _todos.removeWhere((todo) => todo.completed);
  }
}

void main() {
  final vm = TodoViewModel15();
  vm.add('Learn Dart');
  vm.add('Build app');
  vm.toggle(vm.todos.first.id);
  print(vm.todos.map((todo) => '${todo.title}: ${todo.completed}').toList());
}

