// Flutter-like ViewModel example 11, pure Dart
class Todo11 {
  final String id;
  final String title;
  final bool completed;

  const Todo11({required this.id, required this.title, this.completed = false});

  Todo11 copyWith({String? id, String? title, bool? completed}) {
    return Todo11(
      id: id ?? this.id,
      title: title ?? this.title,
      completed: completed ?? this.completed,
    );
  }
}

class TodoViewModel11 {
  final List<Todo11> _todos = [];

  List<Todo11> get todos => List.unmodifiable(_todos);

  void add(String title) {
    if (title.trim().isEmpty) throw ArgumentError('title cannot be empty');
    _todos.add(Todo11(id: DateTime.now().microsecondsSinceEpoch.toString(), title: title));
  }

  void toggle(String id) {
    final index = _todos.indexWhere((todo) => todo.id == id);
    if (index == -1) return;
    final todo = _todos[index];
    _todos[index] = todo.copyWith(completed: !todo.completed);
  }

  void removeCompleted() {
    _todos.removeWhere((todo) => todo.completed);
  }
}

void main() {
  final vm = TodoViewModel11();
  vm.add('Learn Dart');
  vm.add('Build app');
  vm.toggle(vm.todos.first.id);
  print(vm.todos.map((todo) => '${todo.title}: ${todo.completed}').toList());
}

