// Async Dart example 09
Future<String> fetchUser09(int id) async {
  await Future<void>.delayed(Duration(milliseconds: 50));
  if (id < 0) throw ArgumentError('id cannot be negative');
  return 'user_$id';
}

Stream<int> countdown09(int start) async* {
  for (var value = start; value >= 0; value--) {
    await Future<void>.delayed(Duration(milliseconds: 10));
    yield value;
  }
}

Future<void> main() async {
  try {
    final user = await fetchUser09(9);
    print('Fetched: $user');

    await for (final value in countdown09(3)) {
      print('Tick: $value');
    }
  } catch (error) {
    print('Error: $error');
  }
}

