// Repository pattern Dart example 15
class User15 {
  final int id;
  final String name;

  const User15(this.id, this.name);
}

abstract class UserRepository15 {
  Future<List<User15>> findAll();
  Future<User15?> findById(int id);
  Future<void> save(User15 user);
}

class MemoryUserRepository15 implements UserRepository15 {
  final Map<int, User15> _users = {};

  @override
  Future<List<User15>> findAll() async => _users.values.toList();

  @override
  Future<User15?> findById(int id) async => _users[id];

  @override
  Future<void> save(User15 user) async {
    _users[user.id] = user;
  }
}

Future<void> main() async {
  final repo = MemoryUserRepository15();
  await repo.save(User15(1, 'User 15'));
  print((await repo.findById(1))?.name);
}

