// Algorithm Dart example 20
int binarySearch20(List<int> values, int target) {
  var low = 0;
  var high = values.length - 1;

  while (low <= high) {
    final mid = low + ((high - low) ~/ 2);
    final current = values[mid];

    if (current == target) return mid;
    if (current < target) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return -1;
}

List<int> quickSort20(List<int> values) {
  if (values.length <= 1) return values;
  final pivot = values[values.length ~/ 2];
  final less = values.where((value) => value < pivot).toList();
  final equal = values.where((value) => value == pivot).toList();
  final greater = values.where((value) => value > pivot).toList();
  return [...quickSort20(less), ...equal, ...quickSort20(greater)];
}

void main() {
  final sorted = quickSort20([5, 3, 9, 1, 5, 7]);
  print(sorted);
  print(binarySearch20(sorted, 7));
}

