void main(List<String> args) {
  if (args.contains('--help') || args.isEmpty) {
    print('Usage: dart cli_03.dart --name <name> --times <number>');
    return;
  }

  String name = 'World';
  int times = 1;

  for (var index = 0; index < args.length; index++) {
    switch (args[index]) {
      case '--name':
        if (index + 1 < args.length) name = args[++index];
        break;
      case '--times':
        if (index + 1 < args.length) times = int.tryParse(args[++index]) ?? 1;
        break;
    }
  }

  for (var i = 0; i < times; i++) {
    print('Hello, $name!');
  }
}

