// Collections Dart example 06
class Order06 {
  final String customer;
  final List<double> prices;

  Order06(this.customer, this.prices);

  double get total => prices.fold(0, (sum, price) => sum + price);
}

void main() {
  final orders = [
    Order06('Ana', [12.5, 5.0, 3.25]),
    Order06('Bruno', [9.99, 1.99]),
    Order06('Carla', [20.0]),
  ];

  final totalsByCustomer = <String, double>{
    for (final order in orders) order.customer: order.total,
  };

  final expensiveCustomers = totalsByCustomer.entries
      .where((entry) => entry.value > 10)
      .map((entry) => entry.key)
      .toSet();

  print(totalsByCustomer);
  print(expensiveCustomers);
}

